// Blob keys and on-disk blob storage.
//
// Layout inside the data directory:
//   blobs/<key>   blob contents, one regular file per key
//   tmp/          uploads in progress; renamed into blobs/ once complete,
//                 so readers never see a partially written blob
//
// Directory traversal is stopped in two layers: parseKey() rejects keys
// that are not plain relative paths, and BlobStore checks that every path
// it touches resolves strictly inside the blob root, both lexically and
// after following symlinks found on disk (the server never creates
// symlinks itself, but one may be planted in the data directory by hand).

import { createHash, randomBytes } from 'node:crypto';
import { constants as fsConstants } from 'node:fs';
import fs from 'node:fs/promises';
import path from 'node:path';

// NAME_MAX on Linux filesystems, in bytes.
const MAX_SEGMENT_BYTES = 255;

// Filesystem errors that mean "this key cannot be stored as a file here"
// (name too long, a path component clashes with an existing file or
// directory) rather than a server fault.
const KEY_FS_ERRORS = new Set(['ENAMETOOLONG', 'ENOTDIR', 'EISDIR', 'EEXIST', 'EILSEQ']);

export class InvalidKeyError extends Error {
  constructor(message) {
    super(message);
    this.name = 'InvalidKeyError';
  }
}

/**
 * Decodes the percent-encoded key taken from the request path and checks
 * that it is a relative POSIX path that maps to exactly one file under the
 * storage root.
 *
 * @param {string} rawKey  key as it appears in the URL (still percent-encoded)
 * @returns {string} decoded key
 * @throws {InvalidKeyError}
 */
export function parseKey(rawKey) {
  let key;
  try {
    key = decodeURIComponent(rawKey);
  } catch {
    throw new InvalidKeyError('key is not valid percent-encoded UTF-8');
  }

  if (key === '') {
    throw new InvalidKeyError('key is empty');
  }
  if (!key.isWellFormed()) {
    throw new InvalidKeyError('key is not valid Unicode');
  }
  if (key.includes('\0')) {
    throw new InvalidKeyError('key contains a NUL character');
  }
  if (key.startsWith('/')) {
    throw new InvalidKeyError('key must be a relative path');
  }
  for (const segment of key.split('/')) {
    if (segment === '') {
      throw new InvalidKeyError('key contains an empty path segment');
    }
    if (segment === '.' || segment === '..') {
      throw new InvalidKeyError(`key contains a "${segment}" path segment`);
    }
    if (Buffer.byteLength(segment) > MAX_SEGMENT_BYTES) {
      throw new InvalidKeyError(`key path segment is longer than ${MAX_SEGMENT_BYTES} bytes`);
    }
  }
  return key;
}

export class BlobStore {
  /** @param {string} dataDir */
  constructor(dataDir) {
    this.root = path.resolve(dataDir, 'blobs');
    this.tmpDir = path.resolve(dataDir, 'tmp');
  }

  /**
   * Maps a key to its absolute path on disk. parseKey() already rejects
   * every key this refuses; this is the backstop that does not rely on it.
   *
   * @param {string} key
   * @returns {string}
   * @throws {InvalidKeyError} if the resolved path is not strictly inside the root
   */
  pathOf(key) {
    if (typeof key !== 'string' || key === '' || key.includes('\0')) {
      throw new InvalidKeyError('key cannot be stored as a file');
    }
    const segments = key.split('/');
    const target = path.resolve(this.root, ...segments);
    // Resolving must change nothing: a "..", ".", empty or absolute segment
    // would make the result differ from plain concatenation.
    if (!target.startsWith(this.root + path.sep) || target !== this.root + path.sep + segments.join(path.sep)) {
      throw new InvalidKeyError('key resolves outside the storage root');
    }
    return target;
  }

  /**
   * Checks that `dir`, with symlinks followed, is the blob root or inside
   * it. A directory that does not exist yet is judged by its nearest
   * existing ancestor, which is where mkdir would start creating.
   *
   * @param {string} dir  absolute path lexically inside this.root
   * @throws {InvalidKeyError} if it leads out of the root through a symlink
   */
  async #assertInsideRoot(dir) {
    let real;
    for (;;) {
      try {
        real = await fs.realpath(dir);
        break;
      } catch (err) {
        if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
          // No blob root yet, so nothing to escape through.
          if (dir === this.root) return;
          // Not created yet, or a component is a blob: check further up.
          dir = path.dirname(dir);
          continue;
        }
        // ELOOP: a symlink loop planted in the root; ENAMETOOLONG: over PATH_MAX.
        if (err.code === 'ELOOP' || KEY_FS_ERRORS.has(err.code)) {
          throw new InvalidKeyError(`key cannot be stored as a file: ${err.code}`);
        }
        throw err;
      }
    }
    const realRoot = await fs.realpath(this.root);
    if (real !== realRoot && !real.startsWith(realRoot + path.sep)) {
      throw new InvalidKeyError('key resolves outside the storage root through a symlink');
    }
  }

  /**
   * Stores `source` under `key`, replacing any existing blob atomically.
   *
   * @param {string} key  a key accepted by parseKey()
   * @param {AsyncIterable<Buffer>} source
   * @returns {Promise<{ key: string, sha256: string, size: number }>}
   * @throws {InvalidKeyError} if the key cannot be stored as a file
   */
  async put(key, source) {
    const target = this.pathOf(key);
    await fs.mkdir(this.tmpDir, { recursive: true });
    const tmp = path.join(this.tmpDir, `${randomBytes(12).toString('hex')}.part`);

    const hash = createHash('sha256');
    let size = 0;
    try {
      const fh = await fs.open(tmp, 'wx');
      try {
        for await (const chunk of source) {
          hash.update(chunk);
          size += chunk.length;
          for (let offset = 0; offset < chunk.length; ) {
            offset += (await fh.write(chunk, offset)).bytesWritten;
          }
        }
        await fh.sync();
      } finally {
        await fh.close();
      }

      try {
        await renameInto(tmp, target, (dir) => this.#assertInsideRoot(dir));
      } catch (err) {
        if (KEY_FS_ERRORS.has(err.code)) {
          throw new InvalidKeyError(`key cannot be stored as a file: ${err.code}`);
        }
        throw err;
      }
    } catch (err) {
      await fs.rm(tmp, { force: true });
      throw err;
    }

    return { key, sha256: hash.digest('hex'), size };
  }

  /**
   * Opens the blob stored under `key` for reading. The caller owns the
   * returned handle and must close it.
   *
   * @param {string} key  a key accepted by parseKey()
   * @returns {Promise<{ fh: fs.FileHandle, size: number } | null>} null if there is no such blob
   * @throws {InvalidKeyError} if the key cannot name a file here
   */
  async open(key) {
    const target = this.pathOf(key);
    await this.#assertInsideRoot(path.dirname(target));
    let fh;
    try {
      // O_NOFOLLOW: a symlink as the last component is not a blob (list()
      // skips it too) and must not lead out of the root.
      fh = await fs.open(target, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
    } catch (err) {
      // Missing, a path component is a blob rather than a directory, or the
      // key names a symlink.
      if (err.code === 'ENOENT' || err.code === 'ENOTDIR' || err.code === 'ELOOP') return null;
      if (KEY_FS_ERRORS.has(err.code)) {
        throw new InvalidKeyError(`key cannot be stored as a file: ${err.code}`);
      }
      throw err;
    }
    // Size comes from the open handle, so it matches the bytes we will read
    // even if the blob is replaced meanwhile.
    const stat = await fh.stat().catch(async (err) => {
      await fh.close();
      throw err;
    });
    if (!stat.isFile()) {
      // A directory holding other blobs is not a blob itself.
      await fh.close();
      return null;
    }
    return { fh, size: stat.size };
  }

  /**
   * Deletes the blob stored under `key`, then removes any parent directories
   * that are left empty, so the key's path can later be reused as a blob.
   *
   * @param {string} key  a key accepted by parseKey()
   * @returns {Promise<boolean>} false if there was no such blob
   * @throws {InvalidKeyError} if the key cannot name a file here
   */
  async delete(key) {
    const target = this.pathOf(key);
    await this.#assertInsideRoot(path.dirname(target));
    try {
      // unlink() would remove a symlink itself rather than its target, but
      // a symlink is not a blob either, so leave it alone.
      if (!(await fs.lstat(target)).isFile()) return false;
      await fs.unlink(target);
    } catch (err) {
      // Missing, a path component is a blob, or the key names a directory
      // of other blobs: in each case there is no blob to delete.
      if (err.code === 'ENOENT' || err.code === 'ENOTDIR' || err.code === 'EISDIR') return false;
      if (KEY_FS_ERRORS.has(err.code)) {
        throw new InvalidKeyError(`key cannot be stored as a file: ${err.code}`);
      }
      throw err;
    }
    await this.#pruneEmptyDirs(path.dirname(target));
    return true;
  }

  async #pruneEmptyDirs(dir) {
    for (; dir !== this.root && dir.startsWith(this.root + path.sep); dir = path.dirname(dir)) {
      try {
        await fs.rmdir(dir);
      } catch {
        // Not empty (the common case), already gone, or not removable: the
        // blob itself is deleted either way, so stop here.
        return;
      }
    }
  }

  /**
   * Lists all blobs, sorted by key.
   *
   * @returns {Promise<Array<{ key: string, size: number, sha256: string, modified_at: string }>>}
   */
  async list() {
    const blobs = [];
    await this.#walk(this.root, [], blobs);
    return blobs.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  }

  async #walk(dir, prefix, out) {
    let entries;
    try {
      // Names as raw bytes: decoding to strings would silently turn invalid
      // UTF-8 into U+FFFD and report a key that GET can never find.
      entries = await fs.readdir(dir, { withFileTypes: true, encoding: 'buffer' });
    } catch (err) {
      // Nothing stored yet, or the directory vanished while we walked.
      if (err.code === 'ENOENT') return;
      throw err;
    }
    for (const entry of entries) {
      const name = decodeName(entry.name);
      // Only a file put on disk by hand can have such a name; no key reaches it.
      if (name === null) continue;
      const segments = [...prefix, name];
      const full = path.join(dir, name);
      if (entry.isDirectory()) {
        await this.#walk(full, segments, out);
      } else if (entry.isFile()) {
        const meta = await describe(full);
        if (meta) out.push({ key: segments.join('/'), ...meta });
      }
    }
  }
}

// How many times put() recreates parent directories that a concurrent
// delete() pruned between our mkdir and rename.
const RENAME_ATTEMPTS = 5;

// Moves `tmp` to `target`, creating target's parent directories.
// `checkDir` vets the parent directory before mkdir, so nothing gets created
// through a symlink leading elsewhere, and again right before the rename.
async function renameInto(tmp, target, checkDir) {
  const dir = path.dirname(target);
  for (let attempt = 1; ; attempt++) {
    await checkDir(dir);
    try {
      await fs.mkdir(dir, { recursive: true });
      await checkDir(dir);
      await fs.rename(tmp, target);
      return;
    } catch (err) {
      // `tmp` is ours, so ENOENT means a parent directory vanished while
      // mkdir was building the chain or before the rename.
      if (err.code !== 'ENOENT' || attempt >= RENAME_ATTEMPTS) throw err;
    }
  }
}

// ignoreBOM keeps a leading U+FEFF, which is part of the name.
const utf8 = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });

// A file name read as bytes, decoded as a key segment; null if it is not
// valid UTF-8.
function decodeName(bytes) {
  try {
    return utf8.decode(bytes);
  } catch {
    return null;
  }
}

// Size, hash and mtime of one file, all taken from the same open handle so
// they stay consistent even if the blob is replaced concurrently. Returns
// null if the file disappeared in the meantime.
async function describe(file) {
  let fh;
  try {
    fh = await fs.open(file, 'r');
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw err;
  }
  try {
    const stat = await fh.stat();
    const hash = createHash('sha256');
    for await (const chunk of fh.createReadStream({ autoClose: false })) {
      hash.update(chunk);
    }
    return { size: stat.size, sha256: hash.digest('hex'), modified_at: stat.mtime.toISOString() };
  } finally {
    await fh.close();
  }
}
import http from 'node:http';
import { pipeline } from 'node:stream/promises';

import { BlobStore, InvalidKeyError, parseKey } from './blobs.js';

const BLOB_PREFIX = '/blobs/';

/**
 * Creates the Syncbox HTTP server (not yet listening).
 *
 * @param {{ dataDir: string }} options
 * @returns {http.Server}
 */
export function createServer({ dataDir }) {
  const ctx = { store: new BlobStore(dataDir) };
  const server = http.createServer((req, res) => {
    route(req, res, ctx).catch((err) => {
      // A client that hung up mid-request is not a server error.
      if (err?.code === 'ECONNRESET' || err?.code === 'ERR_STREAM_PREMATURE_CLOSE') {
        res.destroy();
        return;
      }
      console.error('unhandled error while serving %s %s:', req.method, req.url, err);
      if (!res.headersSent) {
        sendJson(res, 500, { error: 'internal server error' });
      } else {
        res.destroy();
      }
    });
  });
  return server;
}

async function route(req, res, ctx) {
  const path = pathOf(req.url);

  if (path === '/healthz') {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.setHeader('Allow', 'GET, HEAD');
      return sendJson(res, 405, { error: 'method not allowed' });
    }
    return sendJson(res, 200, { status: 'ok' });
  }

  if (path === '/blobs') {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.setHeader('Allow', 'GET, HEAD');
      return sendJson(res, 405, { error: 'method not allowed' });
    }
    return sendJson(res, 200, await ctx.store.list());
  }

  if (path.startsWith(BLOB_PREFIX) && req.method === 'PUT') {
    return putBlob(req, res, ctx, path.slice(BLOB_PREFIX.length));
  }

  if (path.startsWith(BLOB_PREFIX) && (req.method === 'GET' || req.method === 'HEAD')) {
    return getBlob(req, res, ctx, path.slice(BLOB_PREFIX.length));
  }

  if (path.startsWith(BLOB_PREFIX) && req.method === 'DELETE') {
    return deleteBlob(req, res, ctx, path.slice(BLOB_PREFIX.length));
  }

  return sendJson(res, 404, { error: 'not found' });
}

async function putBlob(req, res, ctx, rawKey) {
  try {
    const key = parseKey(rawKey);
    return sendJson(res, 201, await ctx.store.put(key, req));
  } catch (err) {
    if (err instanceof InvalidKeyError) {
      return sendJson(res, 400, { error: `invalid key: ${err.message}` });
    }
    throw err;
  }
}

async function getBlob(req, res, ctx, rawKey) {
  let blob;
  try {
    blob = await ctx.store.open(parseKey(rawKey));
  } catch (err) {
    if (err instanceof InvalidKeyError) {
      return sendJson(res, 400, { error: `invalid key: ${err.message}` });
    }
    throw err;
  }
  if (!blob) {
    return sendJson(res, 404, { error: 'blob not found' });
  }

  res.writeHead(200, {
    'Content-Type': 'application/octet-stream',
    'Content-Length': blob.size,
  });
  if (req.method === 'HEAD') {
    await blob.fh.close();
    res.end();
    return;
  }
  // The read stream closes the handle once it ends or is destroyed.
  await pipeline(blob.fh.createReadStream(), res);
}

async function deleteBlob(req, res, ctx, rawKey) {
  let deleted;
  try {
    deleted = await ctx.store.delete(parseKey(rawKey));
  } catch (err) {
    if (err instanceof InvalidKeyError) {
      return sendJson(res, 400, { error: `invalid key: ${err.message}` });
    }
    throw err;
  }
  if (!deleted) {
    return sendJson(res, 404, { error: 'blob not found' });
  }
  res.writeHead(204);
  res.end();
}

// Raw path without the query string. Deliberately not using `new URL()`:
// it would normalise away things like `..` segments that later handlers
// must see verbatim in order to reject them.
function pathOf(rawUrl = '/') {
  const q = rawUrl.indexOf('?');
  return q === -1 ? rawUrl : rawUrl.slice(0, q);
}

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(res.req.method === 'HEAD' ? undefined : payload);
}
#!/usr/bin/env node
// Entry point: syncbox-server --data-dir <path> [--port <n>]
// Runs in the foreground until SIGINT/SIGTERM.

import fs from 'node:fs/promises';
import path from 'node:path';

import { ConfigError, USAGE, parseConfig } from './config.js';
import { createServer } from './server.js';

const EXIT_USAGE = 2;

async function main() {
  let config;
  try {
    config = parseConfig(process.argv.slice(2), process.env);
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`syncbox-server: ${err.message}\n\n${USAGE}`);
      process.exit(EXIT_USAGE);
    }
    throw err;
  }

  if (config.help) {
    console.log(USAGE);
    return;
  }

  const dataDir = path.resolve(config.dataDir);
  try {
    await prepareDataDir(dataDir);
  } catch (err) {
    console.error(`syncbox-server: data directory ${dataDir} is not usable: ${err.message}`);
    process.exit(1);
  }

  const server = createServer({ dataDir });

  server.on('error', (err) => {
    console.error(`syncbox-server: cannot listen on port ${config.port}: ${err.message}`);
    process.exit(1);
  });

  server.listen(config.port, () => {
    console.log(`syncbox-server listening on port ${config.port}, data dir ${dataDir}`);
  });

  const shutdown = (signal) => {
    console.log(`syncbox-server: received ${signal}, shutting down`);
    server.close(() => process.exit(0));
    // Don't let idle keep-alive connections hold the process open.
    server.closeIdleConnections();
    setTimeout(() => process.exit(0), 5000).unref();
  };
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);
}

async function prepareDataDir(dir) {
  await fs.mkdir(dir, { recursive: true });
  const stat = await fs.stat(dir);
  if (!stat.isDirectory()) {
    throw new Error('not a directory');
  }
  await fs.access(dir, fs.constants.R_OK | fs.constants.W_OK | fs.constants.X_OK);
}

main().catch((err) => {
  console.error('syncbox-server: fatal error:', err);
  process.exit(1);
});
{
  "name": "syncbox",
  "version": "0.1.0",
  "private": true,
  "description": "Self-hosted file storage with sync: HTTP server + CLI client",
  "type": "module",
  "engines": {
    "node": ">=20 <21"
  },
  "bin": {
    "syncbox-server": "src/server-main.js"
  },
  "scripts": {
    "start": "node src/server-main.js",
    "test": "node --test"
  }
}
# Base image is pinned by project policy: Node.js 20 on Alpine.
FROM node:20-alpine AS base
WORKDIR /app
ENV NODE_ENV=production
# No runtime dependencies yet; package.json is copied for "type": "module".
COPY package.json ./
COPY src/ ./src/
# Runs as an unprivileged user by default; compose overrides the UID/GID
# so files in the bind-mounted data dir belong to the invoking host user.
USER node

FROM base AS server
ENTRYPOINT ["node", "/app/src/server-main.js"]

FROM base AS test
ENV NODE_ENV=test
COPY test/ ./test/
CMD ["node", "--test", "--test-reporter=spec"]
# Single source of truth for building and running Syncbox in Docker.
# Use the wrappers in the repo root (run-server, run-tests) rather than
# invoking these services directly: the wrappers set the SYNCBOX_COMPOSE_*
# variables below from their own command-line arguments.
name: syncbox

x-hardening: &hardening
  init: true
  read_only: true
  tmpfs:
    - /tmp
  cap_drop:
    - ALL
  security_opt:
    - no-new-privileges:true

services:
  server:
    <<: *hardening
    build:
      context: .
      target: server
    image: syncbox-server:dev
    user: "${SYNCBOX_COMPOSE_UID:-1000}:${SYNCBOX_COMPOSE_GID:-1000}"
    # Docker's default bridge instead of a per-project network: run-server
    # starts one compose project per port, and per-project networks would
    # pile up (and exhaust address pools) if a wrapper is killed uncleanly.
    network_mode: bridge
    # Same port inside and outside the container, so the server's own
    # logs and the host-side URL agree.
    ports:
      - "${SYNCBOX_COMPOSE_PORT:-8080}:${SYNCBOX_COMPOSE_PORT:-8080}"
    volumes:
      - type: bind
        source: ${SYNCBOX_COMPOSE_DATA_DIR:-./data}
        target: /data
    command: ["--data-dir", "/data", "--port", "${SYNCBOX_COMPOSE_PORT:-8080}"]
    stop_grace_period: 10s

  test:
    <<: *hardening
    build:
      context: .
      target: test
    image: syncbox-test:dev
    # Tests only talk to servers they spawn on loopback.
    network_mode: none
#!/usr/bin/env bash
# Usage: run-tests
#
# Runs the whole Syncbox test suite inside Docker via docker compose.
# Exits non-zero if any test fails.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
COMPOSE=(docker compose --project-directory "$ROOT" -f "$ROOT/compose.yaml")

# Build output is shown only if the build fails.
if ! build_log="$("${COMPOSE[@]}" build --quiet test 2>&1)"; then
  echo "$build_log" >&2
  echo "run-tests: docker compose build failed" >&2
  exit 1
fi

exec "${COMPOSE[@]}" run --rm -T --quiet-pull test
# Syncbox

Self-hosted file storage with sync: an HTTP server plus a CLI client.
The contract lives in [SYNCBOX-SPEC.md](SYNCBOX-SPEC.md) and
[syncbox-openapi.yaml](syncbox-openapi.yaml).

Implementation: JavaScript on Node.js 20 with no npm dependencies. Everything
runs in Docker (`node:20-alpine`) through docker compose, so the host
only needs Docker with the compose plugin.

## Running

```sh
./run-server --data-dir ./data --port 8080   # foreground; Ctrl+C / SIGTERM stops it
curl http://127.0.0.1:8080/healthz           # {"status":"ok"}
curl -X PUT --data-binary @file.txt http://127.0.0.1:8080/blobs/docs/file.txt  # 201 {"key","sha256","size"}
curl http://127.0.0.1:8080/blobs/docs/file.txt                                # 200 + bytes, 404 if missing
curl -X DELETE http://127.0.0.1:8080/blobs/docs/file.txt                      # 204 no body, 404 if missing
curl http://127.0.0.1:8080/blobs             # 200 [{"key","size","sha256","modified_at"}], sorted by key; [] if empty
./run-tests                                  # full test suite, non-zero exit on failure
```

`run-server` also reads `SYNCBOX_DATA_DIR` / `SYNCBOX_PORT`; flags take
precedence. The data directory is created if missing and bind-mounted into
the container; files are written with the invoking user's UID/GID.

## Keys

A key is a relative POSIX path, percent-decoded from the URL (`%2F` counts as
`/`). `PUT`, `GET` and `DELETE` answer `400` for a key that is empty, absolute,
contains an empty, `.` or `..` segment, a NUL, invalid UTF-8 or a lone
surrogate, or a segment over 255 bytes. Independently of that, the store
resolves every key to a path on disk and refuses it unless the result lies
strictly inside the blob root, both lexically and after following any
symlinks found in the data directory (the server never creates symlinks; a
symlink as the key itself is not treated as a blob).

## Layout

| Path                   | Purpose                                                   |
| ---------------------- | --------------------------------------------------------- |
| `src/server-main.js`   | server entry point (args, data dir checks, signals)       |
| `src/config.js`        | flag/env parsing                                          |
| `src/server.js`        | HTTP routing and handlers                                 |
| `src/blobs.js`         | blob key validation and on-disk storage                   |
| `test/`                | `node:test` suites (unit + spawned-process integration)   |
| `Dockerfile`           | `server` and `test` build targets                         |
