/**
 * Readies the data directory for serving; called once at startup, before
 * any request. Creates blobs/ and tmp/, discards uploads left behind by a
 * previous run that did not exit cleanly, and checks that a rename from
 * tmp/ into blobs/ works, i.e. that blobs can be replaced atomically.
 */
async prepare() {
  await fs.mkdir(this.root, { recursive: true });
  this.discardUploads();
  await fs.mkdir(this.tmpDir, { recursive: true });

  // An empty directory as the probe: list() never reports one, so even if
  // we die before removing it, no phantom blob appears.
  const name = `.rename-probe-${randomBytes(6).toString('hex')}`;
  const probe = path.join(this.tmpDir, name);
  await fs.mkdir(probe);
  try {
    await fs.rename(probe, path.join(this.root, name));
  } catch (err) {
    await fs.rmdir(probe);
    if (err.code === 'EXDEV') {
      throw new Error(`${this.tmpDir} and ${this.root} are on different filesystems, so blobs cannot be replaced atomically`);
    }
