      assert.deepEqual(Buffer.concat(chunks), oldBody);
      assert.deepEqual((await get('big')).body, newBody);
    });

    it('PUTs to different keys in parallel all land intact', async () => {
      const keys = Array.from({ length: 48 }, (_, i) => (i % 3 === 0 ? `k${i}` : `dir${i % 4}/sub${i % 2}/k${i}`));
      const bodies = versions(keys.length, 64 * 1024);
      const results = await Promise.all(keys.map((k, i) => put(k, bodies[i])));
      assert.deepEqual(
        results.map((r) => [r.status, r.json.key, r.json.sha256, r.json.size]),
        keys.map((k, i) => [201, k, sha256(bodies[i]), bodies[i].length]),
      );
      const gets = await Promise.all(keys.map((k) => get(k)));
      gets.forEach((g, i) => assert.deepEqual(g.body, bodies[i], keys[i]));
      assert.deepEqual(
        (await list()).json.map(({ key, sha256 }) => [key, sha256]),
        keys.map((k, i) => [k, sha256(bodies[i])]).sort(([a], [b]) => (a < b ? -1 : 1)),
      );
      assert.deepEqual(await tmpFiles(), []);
    });

    it('an upload in progress is invisible through GET and GET /blobs', async () => {
      assert.equal((await put('doc', 'old')).status, 201);
      const upload = startPut('doc', 8);
      const fresh = startPut('fresh');
      upload.req.write('new ');
      fresh.req.write('half');
      await waitFor('both uploads to reach the disk', async () => (await tmpFiles()).length === 2);

      assert.equal((await get('doc')).text, 'old');
      assert.equal((await get('fresh')).status, 404);
      assert.deepEqual((await list()).json.map((b) => [b.key, b.sha256]), [['doc', sha256('old')]]);
      // The temp files are not reachable by any key either.
      for (const name of await tmpFiles()) {
        assert.ok([400, 404].includes((await get(`..%2Ftmp%2F${name}`)).status));
        assert.equal((await get(`tmp/${name}`)).status, 404);
      }

      upload.req.end('body');
      fresh.req.end(' done');
      assert.equal((await upload.response).status, 201);
      assert.equal((await fresh.response).status, 201);
      assert.equal((await get('doc')).text, 'new body');
      assert.equal((await get('fresh')).text, 'half done');
      assert.deepEqual(await tmpFiles(), []);
    });

    for (const [name, length] of [['with Content-Length', 1024 * 1024], ['chunked', undefined]]) {
      it(`an upload aborted mid-body (${name}) keeps the old blob and leaves no temp file`, async () => {
        assert.equal((await put('kept', 'old')).status, 201);
        const replace = startPut('kept', length);
        const create = startPut('never', length);
        replace.req.write(Buffer.alloc(64 * 1024, 'x'));
        create.req.write(Buffer.alloc(64 * 1024, 'y'));
        await waitFor('both uploads to reach the disk', async () => (await tmpFiles()).length === 2);

        replace.req.destroy();
        create.req.destroy();
        await waitFor('the temp files to be removed', async () => (await tmpFiles()).length === 0);

        assert.equal((await get('kept')).text, 'old');
        assert.equal((await get('never')).status, 404);
        assert.deepEqual((await list()).json.map((b) => [b.key, b.sha256]), [['kept', sha256('old')]]);
      });
    }

    it('rejected uploads leave no temp file', async () => {
      assert.equal((await put('a/b', '1')).status, 201);
      assert.equal((await put('a', 'names a directory')).status, 400);
      assert.equal((await put('a/b/c', 'below a blob')).status, 400);
      assert.deepEqual(await tmpFiles(), []);
      assert.deepEqual((await list()).json.map((b) => b.key), ['a/b']);
    });
  });

